<script>(function(){function inject(){document.querySelectorAll('form[method="post"],form[method="POST"]').forEach(function(form){if(form.querySelector('input[name="_token"]'))return;var input=document.createElement("input");input.type="hidden";input.name="_token";input.value=(window.CI_CSRF?window.CI_CSRF.hash:"");form.appendChild(input);});}if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",inject);}else{inject();}})();</script>
